"use client";

import { forwardRef, type HTMLAttributes, type ReactElement, type Ref } from "react";

import { cn } from "@/lib/cn";

import type { OwnedSlot } from "@/lib/data-slot";

/**
 * IconSwap — one glyph becoming another in place (ADR 0028 §6; craft rule 10;
 * the Icon Swap sheet).
 *
 * Every glyph is rendered once and kept, stacked in one grid cell; `show`
 * picks the visible one. The new glyph fades in on `--ui-duration-base` while
 * growing from the travelled scale to 1, the old one fades out on
 * `--ui-duration-fast` while shrinking to it. The state is an attribute and
 * the motion a CSS transition, so nothing mounts or unmounts, a second change
 * mid-swap turns both glyphs around, and the first render is still.
 *
 * The whole swap is aria-hidden: the host's accessible name (an icon-only
 * Button's aria-label, or the label beside the icon) carries the state.
 */
export interface IconSwapProps<K extends string = string>
  extends Omit<HTMLAttributes<HTMLSpanElement>, "children">,
    OwnedSlot {
  /**
   * Every glyph the swap can show, by name. All of them are rendered; size
   * them from the host (a Button's `[&_svg]:size-4` reaches through).
   */
  icons: Record<K, ReactElement>;
  /** The name of the glyph to show. Changing it is the swap. */
  show: NoInfer<K>;
}

/**
 * Where a hidden glyph sits: a subtle dip to 0.8 and a 2px blur at Full, so a
 * swap reads as one glyph shrinking, softening and re-forming (decided in
 * review, 2026-11-27). Both ride `--ui-motion-travel`, so at Reduced and Off
 * they are 1 and 0px and the swap is a plain cross-fade. The only numbers
 * IconSwap invents; not tokens, because nothing else scales or blurs a glyph.
 */
const HIDDEN_STATE = [
  "[--icon-swap-scale:calc(1-0.2*var(--ui-motion-travel))]",
  "[--icon-swap-blur:calc(2px*var(--ui-motion-travel))]",
];

function IconSwapInner<K extends string>(
  { icons, show, className, ...rest }: IconSwapProps<K>,
  ref: Ref<HTMLSpanElement>,
) {
  return (
    <span
      {...rest}
      ref={ref}
      aria-hidden="true"
      data-slot="icon-swap"
      className={cn("inline-grid shrink-0 place-items-center", HIDDEN_STATE, className)}
    >
      {(Object.keys(icons) as K[]).map((name) => {
        const shown = name === show;
        return (
          <span
            key={name}
            data-slot="icon-swap-glyph"
            data-state={shown ? "shown" : "hidden"}
            className={cn(
              "col-start-1 row-start-1 inline-grid place-items-center",
              "transition-[opacity,scale,filter] ease-(--ui-ease-out)",
              // The destination state's duration is the one a transition
              // runs on: arriving is base, leaving is fast. The shown glyph
              // has NO filter (not blur(0)): a filter left at rest keeps the
              // glyph on its own layer and softens it (craft rule 23).
              shown
                ? "scale-100 opacity-100 duration-(--ui-duration-base)"
                : "blur-(--icon-swap-blur) scale-(--icon-swap-scale) opacity-0 duration-(--ui-duration-fast)",
            )}
          >
            {icons[name]}
          </span>
        );
      })}
    </span>
  );
}

export const IconSwap = forwardRef(IconSwapInner) as <K extends string>(
  props: IconSwapProps<K> & { ref?: Ref<HTMLSpanElement> },
) => ReactElement;

/**
 * Typed documentation for IconSwap.
 *
 * One source for the docs site, Storybook autodocs and MCP answers. Prose that
 * is not here does not exist as far as tooling is concerned (CONVENTIONS §11).
 */

export const iconSwapDoc = {
  lead: "Swaps one glyph for another in place: the old one shrinks and blurs away as the new one re-forms, while the label carries the state.",
  name: "IconSwap",
  status: "experimental",
  summary:
    "The third of ADR 0028's owned motion components, and craft rule 10 made into a component. Every glyph is rendered once and kept, stacked in one grid cell; show names the visible one. The old glyph fades out on --ui-duration-fast while dipping to 0.8 and blurring to 2px; the new one fades in on --ui-duration-base from there, growing back and sharpening, both on --ui-ease-out — one glyph shrinking, softening and re-forming. At rest no glyph has a filter. The state is a data attribute and the motion a CSS transition, so nothing mounts or unmounts, a second change mid-swap turns both glyphs around from where they are, and the first render is still. The whole swap is aria-hidden: the host's accessible name says what happened.",

  anatomy: [
    {
      part: "box",
      slot: "icon-swap",
      notes:
        "One aria-hidden inline-grid span. It has no size of its own: it is as big as the icons in it, which the host sizes — a Button's [&_svg]:size-4 reaches through it.",
    },
    {
      part: "glyph",
      slot: "icon-swap-glyph",
      notes:
        "One span per icon, all in the same cell and centred, each with data-state shown or hidden. Hidden glyphs stay rendered at opacity 0, the travelled scale and blur.",
    },
  ],

  composition: `
IconSwap (icons: Record<name, element>, show: name)
└── box — data-slot="icon-swap", aria-hidden
    └── glyph × n — data-slot="icon-swap-glyph", data-state="shown | hidden"

<Button
  isIconOnly
  aria-label={copied ? "Copied" : "Copy link"}
  icon={<IconSwap icons={{ copy: <Copy />, check: <Check /> }} show={copied ? "check" : "copy"} />}
  onClick={copy}
/>
`,

  props: {
    icons: {
      type: "Record<string, ReactElement>",
      notes:
        "Every glyph the swap can show, by name. All are rendered, in key order; size them from the host, not with a size prop on each icon. Keep the record stable — a glyph added later appears without an entrance.",
    },
    show: {
      type: "keyof icons",
      notes: "The name of the glyph to show. Typed against icons, so a name that is not there does not compile. Changing it is the swap.",
    },
    className: {
      type: "string",
      notes: "Lands on the box, merged last. Colour comes from the host (currentColor), so this is rarely needed.",
    },
  },

  do: [
    "Pass it as a Button's icon slot, and change the host's accessible name with the glyph: aria-label on an icon-only Button, or the visible label beside it. A toggle that keeps its name (Mute) says its state with aria-pressed instead.",
    "Use it for a glyph that means a state: copied, playing, muted, expanded.",
    "Pair it with TextSwap when a Button changes its icon and its words together — the timings match.",
  ],
  dont: [
    "Rely on the glyph to say what happened. IconSwap is aria-hidden on purpose.",
    "Swap a decorative icon for variety. A glyph that changes is read as a state change.",
    "Put a spinner in it for a busy state — Button owns its busy spinner.",
  ],

  a11y: {
    role: "None: the box is aria-hidden, a presentation of state the host names.",
    name: "Never IconSwap's. The host's accessible name (aria-label or visible text) must change with show.",
    keyboard: [],
    focus: "Never focusable. Swapping inside a focused button leaves focus where it is.",
    contrastPairs: [],
    rendersNoColour:
      "IconSwap sets no colour: its glyphs are currentColor in the host's ink, and it changes only opacity and scale, so the pairs are the host component's to declare.",
  },

  forwarding: {
    className: "Lands on the box.",
    ref: "The box span.",
    props: "Native span attributes go to the box; aria-hidden is fixed.",
  },

  motion:
    "All CSS transitions on the tokens. New glyph: opacity 0 → 1, scale 0.8 → 1 and blur 2px → none on --ui-duration-base with --ui-ease-out. Old glyph: opacity 1 → 0, scale 1 → 0.8 and none → blur 2px on --ui-duration-fast. Scale is 1 − 0.2 × --ui-motion-travel and blur 2px × travel; the shown glyph has no filter at all, so it is never left on its own layer. Motion levels (ADR 0028): at Reduced travel is 0, so scale and blur are gone and the cross-fade stays, both durations unchanged; at Off both are 1ms. No glyph is ever removed, so nothing waits for a transition to end.",

  needsDesign: [],

  knownGaps: [
    "The timing borrowed from TextSwap is still badged Derived on the sheet; the dip (×0.8) and blur (2px) were decided in review.",
    "MediaToggle, the site's install pill and the code stage's copy buttons still swap their glyphs by hand, with no motion.",
  ],

  design: "https://app.paper.design/file/01KZ39A2BC286MT85M658NRR4R/p-14-0/490N-1",
} as const;
